import 'regenerator-runtime/runtime'

const cleanBackgroundImageUrl = (string) => string.split(/"/)[1].replace(/^\/+/, '')
const kFormatter = (num) => Math.abs(num) > 999 ? Math.sign(num) * ((Math.abs(num) / 1000).toFixed(1)) + 'k' : Math.sign(num) * Math.abs(num)

const fetchData = async (query) => {
    return new Promise((resolve, reject) => {

        let url, parser

        if (query.type === 'wine') {
            url = `https://www.vivino.com/search/wines?q=${encodeURIComponent(query.name)}`
            parser = parseWine
        }
        if (query.type === 'beer') {
            url = `https://untappd.com/search?q=${encodeURIComponent(query.name)}&type=beer&sort=all`
            parser = parseBeer
        }
        if (query.type === 'liquor') {
            url = `https://distiller.com/search?term=${encodeURIComponent(query.name)}`
            parser = parseLiquor
        }

        fetch(url).then((response) => {
            if (response.status === 429) return reject('Hit rate limit')
            return response.text();
        }).then((html) => {

            const HTMLparser = new DOMParser();
            const doc = HTMLparser.parseFromString(html, 'text/html');
            const data = parser(doc)
            console.table(data);

            if (data) return resolve(data)
            return reject('NOT FOUND')
        })
    })
}

const parseWine = (doc) => {
    const elFirstResult = doc.querySelector('.card')
    if (!elFirstResult) {
        return
    }

    // Name
    const name = elFirstResult.querySelector('.wine-card__name .link-color-alt-grey')?.innerText.trim()

    // Url
    const url = 'https://www.vivino.com' + elFirstResult.querySelector('.wine-card__image-wrapper a')?.getAttribute("href")

    // Rating
    let rating = elFirstResult.querySelector('.average__number')?.innerText.trim()
    rating = rating.replace(',', '.')
    rating = parseFloat(rating)
    rating = rating.toFixed(1)

    // Reviews
    const reviewsString = elFirstResult.querySelector('.average__stars .text-micro')?.innerText.trim()
    const reviews = kFormatter(parseInt(reviewsString))

    // Image
    const backgroundImage = elFirstResult.querySelector('.wine-card__image')?.style?.backgroundImage
    const image = cleanBackgroundImageUrl(backgroundImage)

    // Inverted Percentage
    const invertedPercentage = 100 - parseInt(rating * 10) * 2

    return {
        type: 'wine',
        name: name,
        url: url,
        rating: rating,
        reviews: reviews,
        image: image,
        invertedPercentage: invertedPercentage,
        date: Date.now(),
        source: 'vivino.com'
    }
}

const parseBeer = (doc) => {

    const elFirstResult = doc.querySelector('.beer-item')
    if (!elFirstResult) {
        return
    }

    // Name
    let name = elFirstResult.querySelector('.name')?.innerText.trim()
    const brewery = elFirstResult.querySelector('.brewery')?.innerText.trim()
    if (name !== brewery) {
        name = name + ' - ' + brewery
    }

    // Url
    const url = 'https://untappd.com' + elFirstResult.querySelector('.name a')?.getAttribute("href")

    // Rating
    let rating = elFirstResult.querySelector('.num')?.innerText.trim()
    rating = rating.replace(/[{()}]/g, '')
    rating = parseFloat(rating)
    rating = Math.round(rating * 10) / 10
    rating = rating.toFixed(1)

    // Image
    const image = elFirstResult.querySelector('.label img').getAttribute("href")

    // Inverted Percentage
    const invertedPercentage = 100 - (rating * 10) * 2

    return {
        type: 'beer',
        name: name,
        url: url,
        rating: rating,
        image: image,
        invertedPercentage: invertedPercentage,
        date: Date.now(),
        source: 'untappd.com'
    }

}

const parseLiquor = (doc) => {
    const elFirstResult = doc.querySelector('.spirit')
    if (!elFirstResult) {
        return
    }

    // Name
    let name = elFirstResult.querySelector('.name')?.innerText.trim()

    // Url
    const url = 'https://distiller.com' + elFirstResult.querySelector('a')?.getAttribute("href")

    // Rating
    let rating = elFirstResult.querySelector('.community-rating')?.innerText.trim()
    rating = parseFloat(rating)
    rating = Math.round(rating * 10) / 10
    rating = rating.toFixed(1)

    // Image
    const backgroundImage = elFirstResult.querySelector('.image')?.style?.backgroundImage
    const image = cleanBackgroundImageUrl(backgroundImage)

    // Inverted Percentage
    const invertedPercentage = 100 - (rating * 10) * 2

    return {
        type: 'liquor',
        name: name,
        url: url,
        rating: rating,
        image: image,
        invertedPercentage: invertedPercentage,
        date: Date.now(),
        source: 'distiller.com'
    }

}

chrome.runtime.onMessage.addListener(function(request, sender, sendResponse) {
    if (request.name) {
        fetchData(request).then((response) => {
            sendResponse([response, null])
        }).catch((err) => {
            sendResponse([null, err])
        })
    }
    return true
});

import { init } from './main.js'
import 'regenerator-runtime/runtime'



const documentReadyInterval = setInterval(() => {
    if (document.readyState === "complete") {
        clearInterval(documentReadyInterval);
        console.log('%c%s', 'color: green; font-weight: 900; font-size: 14px;', '🍷 🍷 🍷 Vivino successfully injected')
        init()
    }
}, 200);

import sentinel from 'sentinel-js'
import stringSimilarity from 'string-similarity'
import 'regenerator-runtime/runtime'

const ratingElementClass = 'product-rating'

const isWineBox = (string) => {
    const sbBoxString = 'vinlåda'
    const isBox = string?.toLowerCase().includes(sbBoxString)
    return isBox
}

const getData = (query) => new Promise((resolve, reject) => {
    chrome.runtime.sendMessage(query, (messageResponse) => {
        const [response, error] = messageResponse;
        if (response) {
            return resolve(response);
        }
        reject(error);
    });
});

const getFromLocal = (query) => new Promise((resolve, reject) => {
    chrome.storage.local.get([query], (items) => {
        const data = Object.values(items)[0]
        // Check if data is older then a week
        if (data) {
            const weekUnix = 604800000
            const monthUnix = weekUnix * 4
            const weekAgoUnix = Date.now() - monthUnix
            if (weekAgoUnix > data.date) resolve(undefined)
        }
        resolve(data)
    });
})

const create = async (name, sbType, elWrapper, elItem, productType) => {

    if (isWineBox(sbType)) {
        elWrapper.remove()
        return
    }

    //Get data from local or make request to vivino
    let data = await getFromLocal(name)
    if (!data) {
        data = await getData({
            name: name,
            type: productType
        })
        chrome.storage.local.set({
            [name]: data
        });
        data.request = "External"
        console.table(data)
    } else {
        data.request = "Local"
        console.table(data)
    }

    // Check returned name similarity
    if (data.type === 'wine') {
        const similarity = stringSimilarity.compareTwoStrings(name, data.name);
        const similarityTreshold = .5
        const isNotSimilar = similarity < similarityTreshold
        if (isNotSimilar) {
            elWrapper.remove()
            return
        }
    }
    elWrapper.setAttribute('title', data.source)
    elWrapper.classList.add(data.type)
    elWrapper.href = data.url
    elWrapper.target = "_blank"
    elWrapper.innerHTML = `
        <div class="info">
