    const wineItemSelector = 'main a[href*="/vin"], main a[href*="/ol"], main a[href*="/sprit"]'
    sentinel.on(wineItemSelector, (el) => observer.observe(el))

    const winePageSelector = 'h3'
    sentinel.on(winePageSelector, insertOnProdcutPage)
}

